### Step 1 – Create the API route

Create a file `pages/api/delete-account.js` (or `/app/api/delete-account/route.js` if you’re using the new app directory).  
Add a **save point** first (if you’re using git: `git commit -m "save before delete‑account API"`).

```js
// pages/api/delete-account.js
import { createClient } from '@supabase/supabase-js';
import { getSession } from '@supabase/auth-helpers-nextjs';

// 1️⃣ Initialise Supabase Admin client (server side only)
const supabaseAdmin = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);

export default async function handler(req, res) {
  // 2️⃣ Only allow POST
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  // 3️⃣ Get the logged‑in user from the session cookie
  const { user } = await getSession(req);

  if (!user) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  const { id: userId } = user;

  try {
    // 4️⃣ Delete rows from every user‑specific table
    // Example: user_profile, user_settings, user_notes (add yours)
    const tables = ['user_profile', 'user_settings', 'user_notes'];

    for (const table of tables) {
      await supabaseAdmin
        .from(table)
        .delete()
        .eq('user_id', userId)
        .single();
    }

    // 5️⃣ Remove the user’s files from the bucket
    const { data: files, error: fileErr } = await supabaseAdmin.storage
      .from('user-files')
      .list('', { head: true, limit: 1000, offset: 0 });

    if (!fileErr && files) {
      for (const file of files) {
        const metadata = await supabaseAdmin.storage
          .from('user-files')
          .getPublicUrl(file.name);
        // Supabase storage does not store metadata on the public URL; skip
        // Instead, we delete all files in the folder that matches the user ID
        if (file.name.startsWith(`${userId}/`)) {
          await supabaseAdmin.storage
            .from('user-files')
            .remove([file.name]);
        }
      }
    }

    // 6️⃣ Delete the Auth record
    const { error: deleteAuthErr } = await supabaseAdmin.auth.admin.deleteUser(
      userId
    );

    if (deleteAuthErr) throw deleteAuthErr;

    // 7️⃣ Success
    return res.status(200).json({ success: true });
  } catch (err) {
    console.error('Delete account error:', err);
    return res.status(500).json({ error: err.message });
  }
}
```

🟢 **What changed** – a new API route that accepts a POST from the client, checks the user, deletes their DB rows & files, then removes the Auth record.  
📦 **Safety notes** – the Admin key lives in `process.env.SUPABASE_SERVICE_ROLE_KEY`, **never** exposed to the browser.  

